// ============================================
// FITNESS COACH BHEEM
// Daily Nutrition Calculator
// ============================================

// Get all food records from Google Sheets
const foodLogs = $input.all();

// Get today's date in Indian Standard Time
const today = new Date().toLocaleDateString("en-CA", {
  timeZone: "Asia/Kolkata"
});

// Get the current Telegram user's Chat ID
const currentChatId = String(
  $("Telegram Trigger").first().json.message.chat.id
);

// Initialize nutrition totals
let totalCalories = 0;
let totalProtein = 0;
let totalCarbs = 0;
let totalFat = 0;
let totalFibre = 0;

// Process each food record
for (const item of foodLogs) {
  const row = item.json;

  // Filter records by Telegram Chat ID
  const rowChatId = String(row["Telegram Chat ID"] || "");

  if (rowChatId !== currentChatId) {
    continue;
  }

  // Skip records without a timestamp
  const timestamp = row["Timestamp"];

  if (!timestamp) {
    continue;
  }

  // Convert timestamp to Indian Standard Time date
  const foodDate = new Date(timestamp).toLocaleDateString("en-CA", {
    timeZone: "Asia/Kolkata"
  });

  // Include only today's food records
  if (foodDate !== today) {
    continue;
  }

  // Add nutrition values
  totalCalories += Number(row["Calories"]) || 0;
  totalProtein += Number(row["Protein_g"]) || 0;
  totalCarbs += Number(row["Carbs_g"]) || 0;
  totalFat += Number(row["Fat_g"]) || 0;
  totalFibre += Number(row["Fibre_g"]) || 0;
}

// Round values to two decimal places
totalCalories = Math.round(totalCalories * 100) / 100;
totalProtein = Math.round(totalProtein * 100) / 100;
totalCarbs = Math.round(totalCarbs * 100) / 100;
totalFat = Math.round(totalFat * 100) / 100;
totalFibre = Math.round(totalFibre * 100) / 100;

// Generate a unique daily summary key
const summaryKey = `${today}_${currentChatId}`;

// Return the daily nutrition summary
return [
  {
    json: {
      date: today,
      telegram_chat_id: currentChatId,
      total_calories: totalCalories,
      total_protein_g: totalProtein,
      total_carbs_g: totalCarbs,
      total_fat_g: totalFat,
      total_fibre_g: totalFibre,
      summary_key: summaryKey
    }
  }
];

const foodLogs = $input.all();

foodLogs.sort((a, b) => {
  const timeA = new Date(a.json["Timestamp"] || 0).getTime();
  const timeB = new Date(b.json["Timestamp"] || 0).getTime();

  return timeB - timeA;
});

const recentLogs = foodLogs.slice(0, 10);

if (recentLogs.length === 0) {
  return [
    {
      json: {
        message: "You haven't logged any food yet. Send me a message about what you ate!"
      }
    }
  ];
}

let message = "YOUR RECENT FOOD LOGS\n\n";

for (const item of recentLogs) {
  const row = item.json;

  message += "Log ID: " + (row["Log ID"] || "Missing") + "\n";
  message += "Date: " + (row["Timestamp"] || "Unknown") + "\n";
  message += "Food: " + (row["Food Name"] || "Unknown") + "\n";
  message += "Quantity: " + (row["Quantity"] ?? "?") + " " + (row["Unit"] || "") + "\n";
  message += "Calories: " + (row["Calories"] ?? 0) + " kcal\n";
  message += "Protein: " + (row["Protein_g"] ?? 0) + " g\n";
  message += "-------------------------\n";
}

message += "\nUse the Log ID to identify an entry you want to edit or delete.";

return [
  {
    json: {
      message: message
    }
  }
];

const foodLogs = $input.all();

const messageText = $('Telegram Trigger').first().json.message.text || '';
const chatId = String(
  $('Telegram Trigger').first().json.message.chat.id
);

// Extract the Log ID from commands like /delete 58-0
const match = messageText.trim().match(/^\/delete\s+(\S+)$/);

if (!match) {
  return [
    {
      json: {
        valid: false,
        message: 'Please provide a Log ID.\nExample: /delete 58-0'
      }
    }
  ];
}

const requestedLogId = match[1];

// Find the requested entry among this user's records
const matchingEntry = foodLogs.find(item => {
  return String(item.json['Log ID'] || '') === requestedLogId &&
         String(item.json['Telegram Chat ID'] || '') === chatId;
});

if (!matchingEntry) {
  return [
    {
      json: {
        valid: false,
        log_id: requestedLogId,
        message: 'Food entry not found. Please check the Log ID using /logs.'
      }
    }
  ];
}

return [
  {
    json: {
      valid: true,
      log_id: requestedLogId,
      chat_id: chatId,
      food_name: matchingEntry.json['Food Name'],
      timestamp: matchingEntry.json['Timestamp'],
      message: 'Found the food entry. Ready for deletion.'
    }
  }
];
